package com.mamtrex.hospital.appointment;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="appointments") public class Appointment extends BaseEntity { private String patientId; private String professionalId; private String scheduledAt; private String type; private String status; protected Appointment(){} public Appointment(String patientId, String professionalId, String scheduledAt, String type, String status){this.patientId=patientId; this.professionalId=professionalId; this.scheduledAt=scheduledAt; this.type=type; this.status=status;} public String getPatientId(){return patientId;} public String getProfessionalId(){return professionalId;} public String getScheduledAt(){return scheduledAt;} public String getType(){return type;} public String getStatus(){return status;} }
